  ". Employees cannot register a face ID or be asked to verify — their Profile page shows “Contact admin to use this feature”, and no punch requires a face match.": ". કર્મચારીઓ Face ID નોંધાવી શકતા નથી કે તેમને ચકાસણી માટે કહેવાતું નથી — તેમના પ્રોફાઇલ પેજ પર “આ સુવિધા વાપરવા એડમિનનો સંપર્ક કરો” દેખાય છે, અને કોઈ પંચ માટે ફેસ મેળ જરૂરી નથી.",
