  "A fallback punch must still be from inside the office geofence. It is flagged on the punch and recorded in the Audit Log.": "વૈકલ્પિક પંચ પણ ઓફિસના જિયોફેન્સની અંદરથી જ હોવું જોઈએ. તે પંચ પર ચિહ્નિત થાય છે અને ઓડિટ લોગમાં નોંધાય છે.",
