  "Every message (the clock-in error, the Profile page, the Face ID Registrations screen, the hire screen and the welcome email) follows this choice.": "દરેક સંદેશ (ક્લૉક-ઇન ભૂલ, પ્રોફાઇલ પેજ, Face ID નોંધણી સ્ક્રીન, ભરતી સ્ક્રીન અને સ્વાગત ઇમેઇલ) આ પસંદગીને અનુસરે છે.",
