  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "દરેક કર્મચારી માટે. દરેક વેબ પંચ માટે મંજૂર Face ID સાથે લાઇવ ફેસ મેળ જરૂરી છે; તે બને ત્યાં સુધી, જો તમે નીચેનો વૈકલ્પિક વિકલ્પ મંજૂર ન કરો તો વેબ ક્લૉક-ઇન/આઉટ અવરોધિત રહે છે.",
  "Forgive late arrival when full hours are completed": "પૂરા કલાક પૂરા થાય તો મોડા આગમનને માફ કરો",
  "Grace Period (min)": "ગ્રેસ સમયગાળો (મિનિટ)",
  "Half-Day Limit (hours or fewer)": "અડધા દિવસની મર્યાદા (કલાક અથવા ઓછા)",
  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "કર્મચારી કેટલા દિવસ પાછળ સુધી ઘરેથી કામની વિનંતી કરી શકે. મંજૂર નથી (ભલામણ કરેલ): ફક્ત આજ કે પછીની તારીખ, કારણ કે ભૂતકાળના દિવસ માટે મંજૂર વિનંતી તે દિવસને પછીથી બદલી નાખે છે અને ઘરના લોકેશનની તપાસ પૂરી થઈ શકતી નથી.",
  "HR only": "ફક્ત HR",
  "Late Mark & LOP Rule": "મોડા નિશાન અને પગાર કપાત નિયમ",
  "Late Marks per LOP": "દરેક પગાર કપાત દીઠ મોડા નિશાન",
  "Loading settings…": "સેટિંગ્સ લોડ થઈ રહ્યા છે…",
  "LOP Deduction Unit": "પગાર કપાત એકમ",
  "Manager + HR": "મેનેજર + HR",
  "Manager only": "ફક્ત મેનેજર",
  "mandatory": "ફરજિયાત",
  "Min Hours — Full Day": "ન્યૂનતમ કલાક — પૂરો દિવસ",
  "No LOP (tracking only)": "પગાર કપાત નહીં (ફક્ત નોંધ)",
  "Not allowed (today or later)": "મંજૂર નથી (આજ કે પછી)",
  "Notify": "જાણ કરો",
  "Notify HR and the manager when an employee is absent for N+ consecutive working days without approved leave.": "જ્યારે કર્મચારી મંજૂર રજા વિના સતત N+ કામકાજના દિવસ ગેરહાજર રહે ત્યારે HR અને મેનેજરને જાણ કરો.",
  "off": "બંધ",
  "Off (recommended): a finished day of the half-day limit or fewer is a Half Day; a day above it but short of the full-day minimum stays Present and is shown as “hours not completed” with the minutes short. On: every day below the full-day minimum is a Half Day.": "બંધ (ભલામણ કરેલ): અડધા દિવસની મર્યાદા કે તેથી ઓછા કલાકનો પૂરો થયેલો દિવસ અડધો દિવસ ગણાય છે; તેનાથી વધુ પણ પૂરા દિવસના ન્યૂનતમથી ઓછો દિવસ હાજર રહે છે અને ઓછી પડેલી મિનિટ સાથે “કલાકો પૂરા થયા નથી” તરીકે દેખાય છે. ચાલુ: પૂરા દિવસના ન્યૂનતમથી ઓછો દરેક દિવસ અડધો દિવસ ગણાય છે.",
  "OT Multiplier — Holiday": "OT ગુણક — તહેવાર",
  "OT Multiplier — Regular": "OT ગુણક — સામાન્ય",
  "OT Threshold": "OT મર્યાદા",
  "Overtime Rules": "ઓવરટાઇમ નિયમો",
  "Punch Rules": "પંચ નિયમો",
  "Resets each calendar month": "દર કેલેન્ડર મહિને રીસેટ થાય છે",
  "Save All": "બધું સાચવો",
  "Shift End": "શિફ્ટ સમાપ્તિ",
  "Shift Start": "શિફ્ટ શરૂઆત",
  "Someone who arrives after the grace period but works the full-day hours is marked Present and gets no late mark. The late arrival stays as a note.": "જે વ્યક્તિ ગ્રેસ સમય પછી આવે પણ પૂરા દિવસના કલાક કામ કરે તેને હાજર ગણવામાં આવે છે અને મોડું નિશાન મળતું નથી. મોડું આગમન નોંધ તરીકે રહે છે.",
  "Treat every day below the full day as a Half Day": "પૂરા દિવસથી ઓછા દરેક દિવસને અડધો દિવસ ગણો",
  "Up to 1 day back": "1 દિવસ પાછળ સુધી",
  "Up to 2 days back": "2 દિવસ પાછળ સુધી",
  "Up to 3 days back": "3 દિવસ પાછળ સુધી",
  "Up to 7 days back": "7 દિવસ પાછળ સુધી",
  "Who registers a Face ID": "Face ID કોણ નોંધાવે",
  "Work-from-home requests may start in the past": "ઘરેથી કામની વિનંતી ભૂતકાળથી શરૂ થઈ શકે",
  "Worked hours after the break is deducted. Shift length minus the break makes overtime start exactly at shift end.": "બ્રેક બાદ કર્યા પછીના કામના કલાક. શિફ્ટની લંબાઈ ઓછા બ્રેકથી ઓવરટાઇમ બરાબર શિફ્ટ સમાપ્તિ પર શરૂ થાય છે.",
  "Working Hours": "કામના કલાક",
