  "\"{name}\" will be deactivated. Employees currently assigned this pattern keep it until reassigned — history is preserved.": "\"{name}\" નિષ્ક્રિય કરવામાં આવશે. હાલમાં આ પેટર્ન ધરાવતા કર્મચારીઓ ફરી સોંપાય ત્યાં સુધી તે જાળવી રાખે છે — ઇતિહાસ સચવાય છે.",
