  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "ખાનગી નોકરીદાતા માટે જરૂરી નથી. ફક્ત ત્યાં જ મેળવો જ્યાં સરકારી, PSU અથવા સહાયિત સંસ્થાએ તેની જાણ કરવી પડે, અથવા રાજ્યની પ્રોત્સાહન યોજનાને તેની જરૂર હોય. સ્વ-ઘોષિત, અને રિપોર્ટિંગ મેનેજરથી છુપાવેલ.",
