  "Required for EPF Form 2. Nominees are picked from the family list, so a name is only typed once. Each scheme should total 100%.": "EPF ફોર્મ 2 માટે જરૂરી. નોમિની કુટુંબ યાદીમાંથી પસંદ થાય છે, તેથી નામ ફક્ત એક જ વાર લખવું પડે. દરેક યોજનાનો કુલ સરવાળો 100% થવો જોઈએ.",
