  "Monthly amounts use the selected salary structure and effective date. Enabled structure components appear here; statutory contributions and deductions remain governed by payroll eligibility and statutory rules.": "માસિક રકમ પસંદ કરેલ પગાર માળખા અને અમલની તારીખ મુજબ છે. ચાલુ કરેલા માળખાના ઘટકો અહીં દેખાય છે; કાનૂની ફાળા અને કપાત પેરોલ પાત્રતા અને કાનૂની નિયમો મુજબ જ રહે છે.",
