  "No salary structure applies to this employee. Add or activate one in Settings → Payroll Configuration → Salary Structures; pay components come from it.": "આ કર્મચારીને કોઈ પગાર માળખું લાગુ પડતું નથી. સેટિંગ્સ → પેરોલ ગોઠવણી → પગાર માળખામાં એક ઉમેરો અથવા સક્રિય કરો; પગારના ઘટકો તેમાંથી આવે છે.",
