  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "આ ખાતા માટે ફાઇલ પર કોઈ કર્મચારી રેકોર્ડ નથી (કોઈ કર્મચારી નંબર સોંપાયો નથી), તેથી નીચેની રોજગાર, પગાર, કાનૂની અને ઇતિહાસની વિગતો ઉપલબ્ધ નથી. કર્મચારી તરીકે ક્યારેય ઓનબોર્ડ ન થયેલા એડમિન/સિસ્ટમ લૉગિન માટે આ અપેક્ષિત છે — સંપૂર્ણ રેકોર્ડ જોવા માટે ઓનબોર્ડ થયેલા કર્મચારી તરીકે સાઇન ઇન કરો.",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "આ કર્મચારીએ બેંક વિગતોમાં ફેરફાર જમા કર્યો છે જે તમારી સમીક્ષાની રાહ જુએ છે — તમે નિર્ણય ન લો ત્યાં સુધી તેમની અગાઉની વિગતો પેરોલ માટે સક્રિય રહેશે.",
