  "Select an org unit": "સંસ્થા એકમ પસંદ કરો",
  "Start a Hire action. HR completes the hiring form here, so this employee will go directly to their dashboard after their first password change rather than receiving the self-service onboarding wizard.": "ભરતીની કાર્યવાહી શરૂ કરો. HR અહીં ભરતી ફોર્મ પૂર્ણ કરે છે, તેથી આ કર્મચારી સ્વ-સેવા ઓનબોર્ડિંગ વિઝાર્ડ મેળવવાને બદલે પહેલા પાસવર્ડ ફેરફાર પછી સીધા તેમના ડેશબોર્ડ પર જશે.",
