  "Monthly gross — paid to the employee": "માસિક કુલ પગાર — કર્મચારીને ચૂકવાય છે",
  "Net take-home before income tax": "આવકવેરા પહેલાં ચોખ્ખો હાથમાં આવતો પગાર",
