  "I declare that the information given above is true and complete, and I will submit proofs when payroll asks for them.": "હું જાહેર કરું છું કે ઉપર આપેલી માહિતી સાચી અને સંપૂર્ણ છે, અને પેરોલ માંગે ત્યારે હું પુરાવા જમા કરીશ.",
  "Loading form…": "ફોર્મ લોડ થઈ રહ્યું છે…",
  "No investments or rent to declare under the new regime. Switch to the old regime if you want to claim deductions.": "નવી વ્યવસ્થા હેઠળ જાહેર કરવા માટે કોઈ રોકાણ કે ભાડું નથી. કપાતનો દાવો કરવો હોય તો જૂની વ્યવસ્થા પસંદ કરો.",
  "Please confirm that the information you have declared is correct.": "કૃપા કરીને ખાતરી કરો કે તમે જાહેર કરેલી માહિતી સાચી છે.",
  "Submit for review": "સમીક્ષા માટે જમા કરો",
  "Tax declaration — FY {year}": "કર ઘોષણા — નાણાકીય વર્ષ {year}",
  "Tell payroll what you plan to claim this year so the right tax is deducted each month. You can submit the proofs (receipts, certificates) item by item on the Tax page after you submit.": "આ વર્ષે તમે શેનો દાવો કરવા માંગો છો તે પેરોલને જણાવો, જેથી દર મહિને સાચો કર કપાય. જમા કર્યા પછી તમે કર પેજ પર દરેક બાબતના પુરાવા (રસીદ, પ્રમાણપત્રો) જમા કરી શકો છો.",
