  "Pending requests": "બાકી વિનંતીઓ",
  "Register or update an employee's Face ID in person. It is approved immediately.": "કર્મચારીનું Face ID રૂબરૂ નોંધો અથવા અપડેટ કરો. તે તરત મંજૂર થાય છે.",
  "{name}'s face ID is approved and active immediately — no further review needed.": "{name} નું Face ID તરત મંજૂર અને સક્રિય થાય છે — વધુ સમીક્ષાની જરૂર નથી.",
  "Camera access denied": "કેમેરા એક્સેસ નકારાયો",
  "Capture wasn't clear enough": "કેપ્ચર પૂરતું સ્પષ્ટ ન હતું",
  "Couldn't confirm they're live": "તેઓ સામે જ છે તેની પુષ્ટિ થઈ શકી નહીં",
  "Downloading face models (first time only)…": "ફેસ મોડલ ડાઉનલોડ થઈ રહ્યા છે (ફક્ત પહેલી વાર)…",
  "Face ID registered!": "Face ID નોંધાયું!",
  "Have the employee sit in front of this camera, then start — a quick liveness check confirms it's really them before it's saved.": "કર્મચારીને આ કેમેરા સામે બેસાડો, પછી શરૂ કરો — સાચવતા પહેલાં ઝડપી લાઇવનેસ તપાસ પુષ્ટિ કરે છે કે તે ખરેખર તેઓ જ છે.",
  "Please allow camera access in the browser prompt.": "કૃપા કરીને બ્રાઉઝરના સંદેશમાં કેમેરા એક્સેસની મંજૂરી આપો.",
  "Please try again.": "કૃપા કરીને ફરી પ્રયાસ કરો.",
  "Preparing face recognition": "ફેસ રેકગ્નિશન તૈયાર થઈ રહ્યું છે",
  "Register {name}'s face": "{name} નો ચહેરો નોંધો",
  "Register Face ID — {name}": "Face ID નોંધો — {name}",
  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "Face ID નોંધવા માટે કેમેરા એક્સેસ જરૂરી છે. તમારા બ્રાઉઝરના સેટિંગ્સમાં આ સાઇટ માટે મંજૂરી આપો, પછી ફરી પ્રયાસ કરો.",
  "Registering face ID…": "Face ID નોંધાઈ રહ્યું છે…",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure they're well-lit and centered, then try again.": "નોંધણી માટે સ્વાભાવિક પલકારો અને માથાનું થોડું વળવું બંને જરૂરી છે, અને અમે સમયસર બંને જોઈ શક્યા નહીં. ખાતરી કરો કે પૂરતો પ્રકાશ છે અને ચહેરો વચ્ચે છે, પછી ફરી પ્રયાસ કરો.",
  "Requesting camera access": "કેમેરા એક્સેસ માંગી રહ્યા છીએ",
  "Saving": "સાચવી રહ્યા છીએ",
  "Something went wrong": "કંઈક ખોટું થયું",
  "This will replace their currently registered face ID. Position them in front of the camera and start when ready.": "આ તેમનું હાલમાં નોંધાયેલું Face ID બદલી નાખશે. તેમને કેમેરા સામે ગોઠવો અને તૈયાર થાય ત્યારે શરૂ કરો.",
  "Try Again": "ફરી પ્રયાસ કરો",
  "Update {name}'s face": "{name} નો ચહેરો અપડેટ કરો",
  "Update Face ID — {name}": "Face ID અપડેટ કરો — {name}",
  "We couldn't get a reliably clear capture — this becomes their permanent face ID reference, so it's worth getting right. Try better lighting and have them hold steady.": "અમે વિશ્વસનીય રીતે સ્પષ્ટ કેપ્ચર મેળવી શક્યા નહીં — આ તેમનો કાયમી Face ID સંદર્ભ બને છે, તેથી તે સાચું હોવું જરૂરી છે. વધુ સારો પ્રકાશ રાખો અને તેમને સ્થિર રહેવા કહો.",
  "Contact an HR administrator if you believe this is a mistake.": "જો તમને લાગે કે આ ભૂલ છે તો HR એડમિનિસ્ટ્રેટરનો સંપર્ક કરો.",
  "You don't have permission to manage face ID registrations": "તમને Face ID નોંધણીઓ સંચાલિત કરવાની પરવાનગી નથી",
