  "Country": "દેશ",
  "CURRENT ADDRESS": "વર્તમાન સરનામું",
  "Enter the 6-digit PIN code first. Suggest fills the state, district and city from it. You can also choose the state, then the district, then pick the PIN code from the list.": "પહેલા 6 અંકનો પિન કોડ દાખલ કરો. \"સૂચવો\" તેના પરથી રાજ્ય, જિલ્લો અને શહેર ભરે છે. તમે પહેલા રાજ્ય, પછી જિલ્લો પસંદ કરી યાદીમાંથી પિન કોડ પણ પસંદ કરી શકો છો.",
