  "JPG or PNG — resized automatically to fit. Cropped to a circle on ID cards and reports.": "JPG અથવા PNG — બંધબેસતું થવા આપમેળે માપ બદલાય છે. ID કાર્ડ અને રિપોર્ટ પર ગોળ કાપવામાં આવે છે.",
