  "Credited from the leave policy (Settings > Leave policy) by Company Code, gender and service period.": "રજા નીતિ (સેટિંગ્સ > રજા નીતિ) માંથી કંપની કોડ, જાતિ અને સેવા સમયગાળા મુજબ જમા થાય છે.",
