  "Scan & fill": "સ્કેન કરો અને ભરો",
  "The draft and everything entered so far will be deleted, and its reserved employee number is released. This cannot be undone. To keep it, use Save & exit instead.": "ડ્રાફ્ટ અને અત્યાર સુધી દાખલ કરેલું બધું કાઢી નાખવામાં આવશે, અને તેનો અનામત કર્મચારી નંબર મુક્ત થશે. આ પાછું લઈ શકાશે નહીં. રાખવા માટે તેના બદલે \"સાચવો અને બહાર નીકળો\" વાપરો.",
  "The new hire": "નવા કર્મચારી",
  "The server did not keep: {fields}. Nothing was hired. Open that step, re-enter it, wait for \"Saved\", and press Hire again.": "સર્વરે આ સાચવ્યું નથી: {fields}. કોઈને નોકરી પર રાખ્યા નથી. તે પગલું ખોલો, ફરી દાખલ કરો, \"સચવાયું\" દેખાય ત્યાં સુધી રાહ જુઓ અને ફરી નોકરી પર રાખો દબાવો.",
  "Type the first and last name first. Suggest builds the display name from them.": "પહેલા પ્રથમ અને છેલ્લું નામ લખો. \"સૂચવો\" તેના પરથી પ્રદર્શિત નામ બનાવે છે.",
  "You will need to upload it again before hiring.": "નોકરી પર રાખતા પહેલાં તમારે તે ફરી અપલોડ કરવું પડશે.",
  "Your entries could not be saved, so nothing was hired. {message}": "તમારી એન્ટ્રીઓ સચવાઈ શકી નહીં, તેથી કોઈને નોકરી પર રાખ્યા નથી. {message}",
