  "The new hire cannot register it themselves.": "નવા કર્મચારી તે જાતે નોંધી શકતા નથી.",
  "The new hire registers their Face ID from their Profile page, and HR approves it on": "નવા કર્મચારી પોતાના પ્રોફાઇલ પેજ પરથી Face ID નોંધે છે, અને HR તેને અહીં મંજૂર કરે છે:",
  "The new hire registers their own Face ID from their Profile page; it is active immediately.": "નવા કર્મચારી પોતાના પ્રોફાઇલ પેજ પરથી પોતાનું Face ID નોંધે છે; તે તરત સક્રિય થાય છે.",
  "the record can still be created in Onboarding status.": "રેકોર્ડ હજુ પણ ઓનબોર્ડિંગ સ્થિતિમાં બનાવી શકાય છે.",
  "The record is created in Onboarding status. Optional details (father/mother's name, non-required documents) can still be finished afterward.": "રેકોર્ડ ઓનબોર્ડિંગ સ્થિતિમાં બને છે. વૈકલ્પિક વિગતો (પિતા/માતાનું નામ, બિન-જરૂરી દસ્તાવેજો) પછીથી પણ પૂરી કરી શકાય છે.",
  "Until it is done they cannot clock in on the web.": "તે પૂરું ન થાય ત્યાં સુધી તેઓ વેબ પર ક્લૉક-ઇન કરી શકતા નથી.",
  "Until then they can still clock in from the office; those punches are flagged for HR.": "ત્યાં સુધી તેઓ ઓફિસમાંથી ક્લૉક-ઇન કરી શકે છે; તે પંચ HR માટે ચિહ્નિત થાય છે.",
  "Apply selected": "પસંદ કરેલ લાગુ કરો",
  "Choose a PDF, JPG or PNG": "PDF, JPG અથવા PNG પસંદ કરો",
  "Could not scan this document. Please try again.": "આ દસ્તાવેજ સ્કેન થઈ શક્યો નહીં. કૃપા કરીને ફરી પ્રયાસ કરો.",
  "FOUND IN DOCUMENT": "દસ્તાવેજમાં મળ્યું",
  "Scanning…": "સ્કેન થઈ રહ્યું છે…",
  "Upload a text-based PDF (an offer letter, ID or resume exported as PDF). This reads the actual text in the document and matches recognizable fields — it does not guess anything not on the page.": "ટેક્સ્ટ આધારિત PDF અપલોડ કરો (PDF તરીકે નિકાસ કરેલ ઓફર લેટર, ID અથવા રિઝ્યુમ). આ દસ્તાવેજમાંનું વાસ્તવિક લખાણ વાંચે છે અને ઓળખી શકાય તેવા ફીલ્ડ સાથે મેળવે છે — પેજ પર ન હોય તેવું કંઈ અનુમાન કરતું નથી.",
