  "Couldn't auto-fill bank details for this code — it's still accepted, just enter the bank name/branch manually below.": "આ કોડ માટે બેંક વિગતો આપમેળે ભરી શકાઈ નથી — તે હજુ સ્વીકાર્ય છે, ફક્ત નીચે બેંકનું નામ/શાખા જાતે દાખલ કરો.",
