  "Permanently delete \"{name}\"? This can't be undone, and only works if it has never had a holder — if it has any placement history, this will be rejected; deactivate it instead.": "\"{name}\" કાયમ માટે કાઢી નાખવું છે? આ પાછું લઈ શકાશે નહીં, અને ફક્ત ત્યારે જ કામ કરે છે જ્યારે તેના પર ક્યારેય ધારક ન રહ્યો હોય — જો કોઈ નિમણૂક ઇતિહાસ હોય તો આ નકારાશે; તેના બદલે તેને નિષ્ક્રિય કરો.",
  "Permanently delete \"{name}\"? This can't be undone, and only works if none of its positions have ever been held by anyone — if any have, this will be rejected; deactivate the unit instead.": "\"{name}\" કાયમ માટે કાઢી નાખવું છે? આ પાછું લઈ શકાશે નહીં, અને ફક્ત ત્યારે જ કામ કરે છે જ્યારે તેના કોઈ હોદ્દા પર ક્યારેય કોઈ ધારક ન રહ્યું હોય — જો રહ્યું હોય તો આ નકારાશે; તેના બદલે એકમને નિષ્ક્રિય કરો.",
