  ". Access belongs to that seat—not the reporting chain; employees sharing a seat share its permissions. Use separate positions when employees need different access.": ". એક્સેસ તે જગ્યાનો હોય છે—રિપોર્ટિંગ શ્રેણીનો નહીં; એક જ જગ્યા વહેંચતા કર્મચારીઓ તેની પરવાનગીઓ વહેંચે છે. કર્મચારીઓને અલગ એક્સેસ જોઈએ ત્યારે અલગ પદો વાપરો.",
