  "Team manager": "ટીમ મેનેજર",
  "These permissions belong to this position. The current holder receives them; a future holder receives the same access. Permissions do not automatically pass between a manager and their reports. Give each position its own access below.": "આ પરવાનગીઓ આ પદની છે. વર્તમાન ધારકને તે મળે છે; ભવિષ્યના ધારકને પણ એ જ એક્સેસ મળશે. પરવાનગીઓ મેનેજર અને તેમના રિપોર્ટ વચ્ચે આપોઆપ પસાર થતી નથી. દરેક પદને નીચે તેનો પોતાનો એક્સેસ આપો.",
  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "ટીમ મેનેજર ચાલુ કરવાથી નીચેની સામાન્ય મેનેજર પરવાનગીઓ (કર્મચારીઓ જુઓ, રજા મંજૂર કરો, હાજરી જુઓ) પણ પસંદ થઈ છે, જેથી આ પદ પાસે 0 પરવાનગી ન રહે. સાચવતા પહેલાં જે ન જોઈતી હોય તે અનચેક કરો.",
