  "All {count} manager(s) have approved.": "બધા {count} મેનેજરે મંજૂર કર્યું છે.",
  "All approvals complete. You can now proceed to compute payroll.": "બધી મંજૂરીઓ પૂર્ણ. હવે તમે પેરોલની ગણતરી કરવા આગળ વધી શકો છો.",
  "Approval happens on the Team Approvals page, not here — go to": "મંજૂરી ટીમ મંજૂરી પેજ પર થાય છે, અહીં નહીં — અહીં જાઓ:",
  "Approved by": "દ્વારા મંજૂર",
