  "HR sign-off is the final step before payroll can be processed.": "પેરોલ પ્રોસેસ કરતા પહેલાં HR ની સહી એ અંતિમ પગલું છે.",
  "HR verifies and signs off — unlocks payroll processing": "HR ચકાસીને સહી કરે છે — પેરોલ પ્રોસેસિંગ ખુલે છે",
