  "Waiting for HR/Admin to complete the L1 step directly — no managers are configured for this cycle.": "HR/એડમિન સીધું L1 પગલું પૂરું કરે તેની રાહ જોવાઈ રહી છે — આ ચક્ર માટે કોઈ મેનેજર ગોઠવેલા નથી.",
  "Waiting for other managers to approve. Refresh to check latest status.": "અન્ય મેનેજર મંજૂર કરે તેની રાહ જોવાઈ રહી છે. નવીનતમ સ્થિતિ જોવા રિફ્રેશ કરો.",
  "Your sign-off is required — approve it from": "તમારી સહી જરૂરી છે — અહીંથી મંજૂર કરો:",
  "{amount} total": "કુલ {amount}",
  "All salaries marked as paid. Payroll run for this cycle is complete.": "બધા પગાર ચુકવેલ તરીકે ચિહ્નિત થયા. આ ચક્રનો પેરોલ રન પૂર્ણ થયો.",
  "Checking salary transfer readiness…": "પગાર ટ્રાન્સફરની તૈયારી તપાસી રહ્યા છીએ…",
  "Confirm and Lock": "પુષ્ટિ કરો અને લૉક કરો",
