  "Confirm salary transfer?": "પગાર ટ્રાન્સફરની પુષ્ટિ કરવી છે?",
  "Download NEFT CSV": "NEFT CSV ડાઉનલોડ કરો",
  "Employees have acknowledged their payslips. Confirm the salary transfer to lock bank details and generate the NEFT CSV.": "કર્મચારીઓએ તેમની પગાર સ્લિપ સ્વીકારી છે. બેંક વિગતો લૉક કરવા અને NEFT CSV બનાવવા માટે પગાર ટ્રાન્સફરની પુષ્ટિ કરો.",
  "Failed to confirm the salary transfer.": "પગાર ટ્રાન્સફરની પુષ્ટિ થઈ શકી નહીં.",
  "Failed to download the bank transfer file.": "બેંક ટ્રાન્સફર ફાઇલ ડાઉનલોડ થઈ શકી નહીં.",
  "Failed to mark as paid.": "ચુકવેલ તરીકે ચિહ્નિત કરી શકાયું નહીં.",
