  "Paid": "ચુકવેલ",
  "Preparing CSV…": "CSV તૈયાર થઈ રહી છે…",
  "Salary transfer locked for {count} employee(s). Download the NEFT CSV and submit it to your bank before marking payroll paid.": "{count} કર્મચારી માટે પગાર ટ્રાન્સફર લૉક થયું. પેરોલને ચુકવેલ ચિહ્નિત કરતા પહેલાં NEFT CSV ડાઉનલોડ કરીને તમારી બેંકમાં જમા કરો.",
  "Salary transfer readiness is unavailable.": "પગાર ટ્રાન્સફરની તૈયારીની માહિતી ઉપલબ્ધ નથી.",
  "This locks the current bank details and net pay for all {count} employee(s) into a transfer batch. Download the NEFT CSV after confirmation and submit it through your bank before marking payroll paid.": "આ બધા {count} કર્મચારીની વર્તમાન બેંક વિગતો અને ચોખ્ખો પગાર એક ટ્રાન્સફર બેચમાં લૉક કરે છે. પુષ્ટિ પછી NEFT CSV ડાઉનલોડ કરો અને પેરોલને ચુકવેલ ચિહ્નિત કરતા પહેલાં તેને તમારી બેંક મારફતે જમા કરો.",
  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "આ બધી {count} પગાર સ્લિપ (કુલ {amount}) ને ચુકવેલ ચિહ્નિત કરે છે અને આ પેરોલ રન બંધ કરે છે. આ પોતે પૈસા ટ્રાન્સફર કરતું નથી — તે નોંધે છે કે ટ્રાન્સફર થઈ ચૂક્યું છે. આ પાછું ફેરવી શકાતું નથી.",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "આ બધી {count} પગાર સ્લિપ (કુલ {amount}) ને ચુકવેલ ચિહ્નિત કરે છે અને આ પેરોલ રન બંધ કરે છે. આ પોતે પૈસા ટ્રાન્સફર કરતું નથી — તે નોંધે છે કે ટ્રાન્સફર થઈ ચૂક્યું છે. આ પાછું ફેરવી શકાતું નથી.",
