  "This recalculates salaries for all {count} employee in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "આ ચક્રના બધા {count} કર્મચારીના પગારની ફરીથી શરૂઆતથી ગણતરી કરે છે અને વર્તમાન આંકડા બદલી નાખે છે — આ પગાર સ્લિપ પર અગાઉ કરેલા મેન્યુઅલ બોનસ કે ખર્ચ પરત ચુકવણીના ફેરફારો સહિત. આ પાછું ફેરવી શકાતું નથી.",
  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "આ ચક્રના બધા {count} કર્મચારીઓના પગારની ફરીથી શરૂઆતથી ગણતરી કરે છે અને વર્તમાન આંકડા બદલી નાખે છે — આ પગાર સ્લિપ પર અગાઉ કરેલા મેન્યુઅલ બોનસ કે ખર્ચ પરત ચુકવણીના ફેરફારો સહિત. આ પાછું ફેરવી શકાતું નથી.",
