  "{served} of {required} days served ({short} short). A recovery of {amount} has been calculated. Confirm with HR or finance whether this recovery applies before finalising.": "{required} માંથી {served} દિવસ પૂરા કર્યા ({short} ઓછા). {amount} ની વસૂલાત ગણવામાં આવી છે. અંતિમ કરતા પહેલાં HR અથવા ફાઇનાન્સ સાથે પુષ્ટિ કરો કે આ વસૂલાત લાગુ પડે છે કે નહીં.",
