  "Deductions exceed earnings — this amount is owed back by the employee, not paid to them.": "કપાત કમાણી કરતાં વધુ છે — આ રકમ કર્મચારીએ પરત ચૂકવવાની છે, તેમને ચૂકવવાની નથી.",
