  "Finalize this settlement?": "આ સેટલમેન્ટ અંતિમ કરવું છે?",
  "Finalized by {name}": "{name} દ્વારા અંતિમ કર્યું",
  "Finalizing…": "અંતિમ થઈ રહ્યું છે…",
