  "Net Recoverable from Employee": "કર્મચારી પાસેથી વસૂલવાપાત્ર ચોખ્ખી રકમ",
  "Notice Period Recovery": "નોટિસ સમયગાળા વસૂલાત",
  "Notice period shortfall:": "નોટિસ સમયગાળાની ઘટ:",
  "Other Adjustment (+/−)": "અન્ય ગોઠવણ (+/−)",
  "Other Adjustment Note": "અન્ય ગોઠવણની નોંધ",
  "Other Adjustment: {amount}": "અન્ય ગોઠવણ: {amount}",
  "Pro-rata Salary": "પ્રમાણસર પગાર",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "પ્રમાણસર પગાર, રજા રોકડમાં રૂપાંતર અને નોટિસ સમયગાળાની ઘટ આપોઆપ ગણાય છે (CTC ÷ 30, કમાયેલી રજાનું બાકી) — આ સમીક્ષા માટેનો પ્રારંભિક અંદાજ છે, અંતિમ આંકડો નથી. ગ્રેજ્યુઇટી, બોનસ, ખર્ચ પરત ચુકવણી, એડવાન્સ અને TDS હંમેશા જાતે દાખલ કરવામાં આવે છે.",
  "Settlement finalized.": "સેટલમેન્ટ અંતિમ થયું.",
  "Settlement updated.": "સેટલમેન્ટ અપડેટ થયું.",
  "This is a recovery — the employee owes the company (net payable may be negative)": "આ વસૂલાત છે — કર્મચારીએ કંપનીને ચૂકવવાના છે (ચોખ્ખી ચૂકવવાપાત્ર રકમ નેગેટિવ હોઈ શકે છે)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "આ ફુલ અને ફાઇનલ સેટલમેન્ટને {amount} ની ચોખ્ખી ચૂકવવાપાત્ર રકમ પર લૉક કરે છે. અંતિમ થયા પછી આ સેટલમેન્ટની કોઈ પણ વિગત — ગ્રેજ્યુઇટી, બોનસ, ખર્ચ પરત ચુકવણી, એડવાન્સ, TDS કે ગોઠવણ — ફરી સંપાદિત કરી શકાશે નહીં. આ પાછું ફેરવી શકાતું નથી.",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "આ ફુલ અને ફાઇનલ સેટલમેન્ટને કર્મચારી પાસેથી {amount} ની ચોખ્ખી વસૂલવાપાત્ર રકમ પર લૉક કરે છે. અંતિમ થયા પછી આ સેટલમેન્ટની કોઈ પણ વિગત — ગ્રેજ્યુઇટી, બોનસ, ખર્ચ પરત ચુકવણી, એડવાન્સ, TDS કે ગોઠવણ — ફરી સંપાદિત કરી શકાશે નહીં. આ પાછું ફેરવી શકાતું નથી.",
