  "Add the people who depend on the employee or who may be nominated below. A person is added once and can be picked as a nominee.": "કર્મચારી પર આધારિત અથવા નોમિની બની શકે તેવા લોકોને નીચે ઉમેરો. વ્યક્તિ એક વાર ઉમેરાય છે અને તેને નોમિની તરીકે પસંદ કરી શકાય છે.",
