  "on any section to go back and change it — nothing is sent to HR until you press": "કોઈપણ વિભાગ પર ક્લિક કરીને પાછા જઈ બદલો — જ્યાં સુધી તમે દબાવશો નહીં ત્યાં સુધી HR ને કંઈ મોકલાતું નથી",
  "Optional — not submitted": "વૈકલ્પિક — જમા કર્યું નથી",
  "Required — not yet submitted": "જરૂરી — હજુ જમા કર્યું નથી",
  "Review everything below before submitting. Use": "જમા કરતા પહેલાં નીચેનું બધું તપાસો. વાપરો",
  "{name} preview": "{name} પ્રીવ્યૂ",
  "Checked against every other employee before the upload goes through — enter it first.": "અપલોડ પૂર્ણ થતા પહેલાં બીજા દરેક કર્મચારી સામે ચકાસાય છે — પહેલાં તે દાખલ કરો.",
  "Drag and drop a file onto any row below, or click Upload. Accepted: PDF, JPG, PNG · Max 5 MB each.": "નીચેની કોઈપણ પંક્તિ પર ફાઇલ ખેંચીને છોડો, અથવા અપલોડ પર ક્લિક કરો. સ્વીકાર્ય: PDF, JPG, PNG · દરેક વધુમાં વધુ 5 MB.",
  "e.g. ABCDE1234F": "ઉદા. ABCDE1234F",
  "File is too large ({size} MB) — the limit is 5 MB.": "ફાઇલ ખૂબ મોટી છે ({size} MB) — મર્યાદા 5 MB છે.",
  "Only PDF, JPG, and PNG files are accepted.": "ફક્ત PDF, JPG અને PNG ફાઇલો સ્વીકારાય છે.",
  "PAN Number": "PAN નંબર",
  "Remove this document": "આ દસ્તાવેજ કાઢી નાખો",
  "Face ID approved": "Face ID મંજૂર",
  "Face ID not yet registered": "Face ID હજુ નોંધાયું નથી",
  "Face ID registered": "Face ID નોંધાયું",
  "Face ID rejected — please register again": "Face ID નામંજૂર — કૃપા કરીને ફરી નોંધણી કરો",
  "Face ID submitted — pending HR approval": "Face ID જમા થયું — HR ની મંજૂરી બાકી",
  "Register Again": "ફરી નોંધણી કરો",
  "Register Face ID": "Face ID નોંધાવો",
  "You won't be able to submit your onboarding profile until this step is complete.": "આ પગલું પૂર્ણ ન થાય ત્યાં સુધી તમે તમારી ઓનબોર્ડિંગ પ્રોફાઇલ જમા કરી શકશો નહીં.",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, and it takes effect immediately.": "તમારી સંસ્થાને વેબ ક્લૉક-ઇન/આઉટ માટે નોંધાયેલ Face ID જોઈએ છે. અહીં એક વાર નોંધણી કરો — તે ખરેખર તમે જ છો તેની પુષ્ટિ માટે અમે ઝડપી લાઇવનેસ ચકાસણી કરીએ છીએ, અને તે તરત અમલમાં આવે છે.",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, then send it to HR for approval.": "તમારી સંસ્થાને વેબ ક્લૉક-ઇન/આઉટ માટે નોંધાયેલ Face ID જોઈએ છે. અહીં એક વાર નોંધણી કરો — તે ખરેખર તમે જ છો તેની પુષ્ટિ માટે અમે ઝડપી લાઇવનેસ ચકાસણી કરીએ છીએ, પછી મંજૂરી માટે HR ને મોકલીએ છીએ.",
