  "“Sent” means the mail server accepted the email. It does not prove the employee's inbox received it.": "“મોકલાયું” નો અર્થ છે કે મેઇલ સર્વરે ઇમેઇલ સ્વીકાર્યો. તે સાબિત કરતું નથી કે કર્મચારીના ઇનબોક્સમાં પહોંચ્યો.",
