  "Location access is required for office punch in/out. Please allow location in your browser settings.": "ઓફિસ પંચ ઇન/આઉટ માટે લોકેશન એક્સેસ જરૂરી છે. કૃપા કરીને તમારા બ્રાઉઝર સેટિંગ્સમાં લોકેશનને મંજૂરી આપો.",
  "Location access is required for work-from-home punch in/out. Please allow location in your browser settings.": "ઘરેથી કામના પંચ ઇન/આઉટ માટે લોકેશન એક્સેસ જરૂરી છે. કૃપા કરીને તમારા બ્રાઉઝર સેટિંગ્સમાં લોકેશનને મંજૂરી આપો.",
  "Please register your Face ID first (Profile > Register My Face), then come back to punch in.": "કૃપા કરીને પહેલા તમારું Face ID નોંધાવો (પ્રોફાઇલ > મારો ચહેરો નોંધાવો), પછી પંચ ઇન કરવા પાછા આવો.",
