  "Punched in successfully.": "પંચ ઇન સફળ થયું.",
  "Punched out successfully.": "પંચ આઉટ સફળ થયું.",
  "Too many failed face verification attempts. Please wait {time} before trying again.": "ચહેરાની ચકાસણીના ઘણા નિષ્ફળ પ્રયાસો થયા. ફરી પ્રયાસ કરતાં પહેલાં કૃપા કરીને {time} રાહ જુઓ.",
  "Unable to determine your location. Please check your device's location settings and try again.": "તમારું લોકેશન નક્કી કરી શકાયું નથી. કૃપા કરીને તમારા ડિવાઇસના લોકેશન સેટિંગ્સ તપાસો અને ફરી પ્રયાસ કરો.",
