  "Pre-Joining": "જોડાતા પહેલાં",
  "Reason: {reason}": "કારણ: {reason}",
  "Registered on {date} by {name}.": "{name} દ્વારા {date} ના રોજ નોંધાયું.",
  "Registered on {date}.": "{date} ના રોજ નોંધાયું.",
  "Reviewed on {date} by {name}.": "{name} દ્વારા {date} ના રોજ સમીક્ષા થઈ.",
  "Reviewed on {date}.": "{date} ના રોજ સમીક્ષા થઈ.",
  "Submitted on {date}. It can be approved from the Approvals page.": "{date} ના રોજ જમા થયું. તેને મંજૂરીઓ પેજ પરથી મંજૂર કરી શકાય છે.",
  "{label} is required.": "{label} જરૂરી છે.",
  "{name}'s date of birth cannot be in the future.": "{name} ની જન્મ તારીખ ભવિષ્યની ન હોઈ શકે.",
  "A family member": "પરિવારના સભ્ય",
  "Aadhaar is required.": "આધાર જરૂરી છે.",
  "Aadhaar must be exactly 12 digits.": "આધાર બરાબર 12 અંકનો હોવો જોઈએ.",
  "Account holder name can only contain letters, spaces, hyphens and apostrophes.": "ખાતાધારકના નામમાં ફક્ત અક્ષરો, જગ્યા, હાઇફન અને એપોસ્ટ્રોફી હોઈ શકે.",
  "Account holder name is required.": "ખાતાધારકનું નામ જરૂરી છે.",
  "Account number is required.": "ખાતા નંબર જરૂરી છે.",
  "Add at least one qualification, with the institution, before continuing.": "આગળ વધતા પહેલાં સંસ્થા સાથે ઓછામાં ઓછી એક લાયકાત ઉમેરો.",
  "Annual fixed CTC must be greater than zero, or left blank.": "વાર્ષિક નિશ્ચિત CTC શૂન્યથી વધુ હોવો જોઈએ, અથવા ખાલી રાખો.",
  "Date of birth cannot be in the future.": "જન્મ તારીખ ભવિષ્યની ન હોઈ શકે.",
  "Date of birth is not a valid date.": "જન્મ તારીખ માન્ય તારીખ નથી.",
  "Date of birth is required.": "જન્મ તારીખ જરૂરી છે.",
  "Employee must be at least {years} years old.": "કર્મચારીની ઉંમર ઓછામાં ઓછી {years} વર્ષ હોવી જોઈએ.",
